// Bee and Cairn: Rippily traffic ingest.
//
// Identity is dropped here and never written downstream. The payload from
// /api/rippily-webhook carries participant.name, participant.tagname and
// participant.email. None of the three reach the sheet. The pseudonymous
// participant.id is enough to count unique visitors and pair a session.
//
// Workflow static data holds two small maps between executions: recently seen
// delivery ids for deduplication, and open joins waiting for their matching
// leave. Both are pruned on every run so they cannot grow without bound.

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
store.open = store.open || {};

const now = Date.now();
const DEDUP_MS = 24 * 60 * 60 * 1000;   // a retry older than this is not a retry
const OPEN_MS  = 12 * 60 * 60 * 1000;   // a join with no leave is abandoned

for (const [k, t] of Object.entries(store.seen)) {
  if (now - t > DEDUP_MS) delete store.seen[k];
}
for (const [k, s] of Object.entries(store.open)) {
  if (now - new Date(s.startedAt).getTime() > OPEN_MS) delete store.open[k];
}

// Every row carries the same columns so the sheet stays rectangular.
function row(over) {
  return Object.assign({
    type: '',
    recordedAt: new Date().toISOString(),
    occurredAt: '',
    action: '',
    participantId: '',
    role: '',
    rippleId: '',
    rippleName: '',
    waveName: '',
    durationSeconds: '',
    verified: '',
    detail: ''
  }, over);
}

const rows = [];

for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const nowIso = new Date().toISOString();

  const action = body.action;
  const participantId = (body.participant && body.participant.id) || '';
  const rippleId = (body.ripple && body.ripple.id) || '';
  const rippleName = (body.ripple && body.ripple.name) || '';
  const waveName = (body.wave && body.wave.name) || '';
  const role = (body.participant && body.participant.role) || '';
  const verified = body.verified === true;

  // The field names in Rippily's payload are inferred, not documented. Anything
  // that does not parse goes to quarantine rather than the floor, so the first
  // week of real deliveries can teach you what the shape actually is.
  if (action !== 'joined' && action !== 'left') {
    rows.push(row({
      type: 'quarantine',
      occurredAt: nowIso,
      action: String(body.event || 'missing'),
      rippleName,
      verified,
      detail: JSON.stringify(body.raw || body).slice(0, 500)
    }));
    continue;
  }

  const deliveryId = body.deliveryId || [action, participantId, body.occurredAt || nowIso].join('|');
  if (store.seen[deliveryId]) continue;
  store.seen[deliveryId] = now;

  const occurredAt = body.occurredAt || nowIso;

  rows.push(row({
    type: 'event',
    occurredAt,
    action,
    participantId,
    role,
    rippleId,
    rippleName,
    waveName,
    verified
  }));

  const key = (participantId || 'anon') + '|' + (rippleId || 'unknown');

  if (action === 'joined') {
    store.open[key] = { startedAt: occurredAt };
    continue;
  }

  // A leave closes the open join and becomes one session with a duration.
  const open = store.open[key];
  delete store.open[key];

  let durationSeconds = '';
  let detail = 'no matching join in window';

  if (open) {
    const seconds = Math.round((new Date(occurredAt) - new Date(open.startedAt)) / 1000);
    durationSeconds = Math.max(0, seconds);
    detail = '';
  }

  rows.push(row({
    type: 'session',
    occurredAt: open ? open.startedAt : occurredAt,
    action: 'session',
    participantId,
    role,
    rippleId,
    rippleName,
    waveName,
    durationSeconds,
    verified,
    detail
  }));
}

return rows.map((json) => ({ json }));
